package com.edro08.crossrelay.core

import android.util.Log

/**
 * Bridge to the Go Core AAR generated by `gomobile bind ./mobile`.
 * Uses reflection so the Android project compiles cleanly even before `crossrelay.aar` is built.
 */
object CoreBridge {
    private const val TAG = "CoreBridge"
    private const val CLASS_NAME = "mobile.Mobile"

    @Volatile
    var controlPort: Int = 0
        private set

    @Volatile
    var activeP2PPort: Int = 0
        private set

    @Volatile
    var isNativeLoaded: Boolean = false
        private set

    fun startNode(dataDir: String, deviceName: String, defaultDownloadDir: String): Int {
        return try {
            val clazz = Class.forName(CLASS_NAME)
            val startMethod = clazz.getMethod(
                "startNode",
                String::class.java,
                String::class.java,
                String::class.java
            )
            val port = (startMethod.invoke(null, dataDir, deviceName, defaultDownloadDir) as Long).toInt()
            controlPort = port
            activeP2PPort = activePort()
            isNativeLoaded = true
            port
        } catch (e: ClassNotFoundException) {
            Log.w(TAG, "crossrelay.aar not bundled yet; running UI in standby mode.")
            isNativeLoaded = false
            0
        } catch (e: Throwable) {
            Log.e(TAG, "Failed starting Go Core node", e)
            isNativeLoaded = false
            0
        }
    }

    fun stopNode() {
        try {
            val clazz = Class.forName(CLASS_NAME)
            clazz.getMethod("stopNode").invoke(null)
        } catch (_: Throwable) {
        } finally {
            controlPort = 0
            activeP2PPort = 0
        }
    }

    fun activePort(): Int {
        return try {
            val clazz = Class.forName(CLASS_NAME)
            (clazz.getMethod("activePort").invoke(null) as Long).toInt()
        } catch (_: Throwable) {
            0
        }
    }
}
